s["unknown"] == "available_at_unknown" else: assert next(r for r in selected if r["id"] == "unknown")["_retrospective_snapshot"] is True assert rows == frozen calls = Counter(call.args[0] for call in parse.call_args_list) # One boundary preparation plus that boundary's deliberately placed event. > assert calls[window.start] <= 3 E assert 1003 <= 3
